import argparse, subprocess, sys, datetime, base64
from pathlib import Path

FILES = {
    'tools/py/pack_fetcher.py': b'',
    'tools/ps1/run_pack_fetcher.ps1': b'',
    'tools/ps1/register_pack_fetcher.ps1': b'',
    'config/github_fetch.yaml': b'',
    'docs/pack_fetcher.md': b'',
}

def run(a, cwd=None, check=True): subprocess.run(a, cwd=cwd, check=check)

def find_root(seed: Path) -> Path:
    p = seed
    for _ in range(8):
        if (p/'.git').exists(): return p
        p = p.parent
    return seed

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--repo-root', default='')
    a=ap.parse_args()
    here=Path(__file__).resolve()
    root = Path(a.repo_root) if a.repo_root else find_root(here)
    if not (root/'.git').exists():
        print('Repo root not found', file=sys.stderr); return 2

    # write files
    for rel, b64 in FILES.items():
        p = root / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))

    # git branch/commit/push
    step='PA-310'; branch=f'step/{step}-pack-fetcher'
    ts=datetime.datetime.now().strftime('%Y%m%d_%H%M')
    run(['git','checkout','-B',branch], root)
    run(['git','add','-A'], root)
    run(['git','commit','-m', f'{step}: add GitHub/URL pack fetcher + wrappers + config'], root, check=False)
    run(['git','push','-u','origin',branch], root, check=False)
    print(f'{step} done.')
    return 0

if __name__=='__main__': sys.exit(main())